local PlanerMaker = {}
local PRODUCTS = {
    simple_wood_planer = { name = "Preprost leseni gladilnik", woodCost = 4, ironCost = 2, steelCost = 1, time = 5, cost = 180, science = 20, happiness = 1, description = "Preprost leseni gladilnik za glajenje." },
    iron_reinforced_planer = { name = "Železnookrepljen gladilnik", woodCost = 3, ironCost = 2, steelCost = 2, time = 8, cost = 440, science = 32, happiness = 2, prestige = 2, description = "Železnookrepljen gladilnik za trgovce." },
    silver_blade_planer = { name = "Srebrnorezni gladilnik", woodCost = 3, ironCost = 2, silverCost = 1, steelCost = 2, time = 12, cost = 1000, science = 48, happiness = 2, prestige = 6, description = "Srebrnorezni gladilnik za plemiče." },
    gold_trimmed_planer = { name = "Zlatookrasni gladilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 2, time = 16, cost = 2300, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasni gladilnik za visoke plemiče." },
    jewel_set_planer = { name = "Draguljasta gladilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 2, jewelCost = 1, time = 20, cost = 4800, science = 78, happiness = 5, prestige = 27, description = "Gladilnik z draguljem za visoko plemstvo." },
    royal_grand_planer = { name = "Kraljevski veliki gladilnik", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 2, jewelCost = 2, pearlCost = 2, time = 27, cost = 10000, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski gladilnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    planer_workshop = { name = "Gladilniška delavnica", cost = { gold = 300, wood = 160, stone = 140, iron = 6, steel = 4 }, upkeep = 7, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, steel = 6 }, upkeep = 26, qualityBonus = 18 },
    master_machinist_atelier = { name = "Mojstrski strojniški atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_machinery_palace = { name = "Kraljevska strojna palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
PlanerMaker.woodStock = 20; PlanerMaker.ironStock = 12; PlanerMaker.steelStock = 12; PlanerMaker.silverStock = 6; PlanerMaker.goldStock = 6; PlanerMaker.jewelStock = 4; PlanerMaker.pearlStock = 4
PlanerMaker.productStock = {}; PlanerMaker.buildings = {}; PlanerMaker.maker = nil; PlanerMaker.activeMaking = {}; PlanerMaker.totalProducts = 0; PlanerMaker.dayTimer = 0
function PlanerMaker.init() PlanerMaker.woodStock=20; PlanerMaker.ironStock=12; PlanerMaker.steelStock=12; PlanerMaker.silverStock=6; PlanerMaker.goldStock=6; PlanerMaker.jewelStock=4; PlanerMaker.pearlStock=4; PlanerMaker.productStock={}; PlanerMaker.buildings={}; PlanerMaker.maker=nil; PlanerMaker.activeMaking={}; PlanerMaker.totalProducts=0; PlanerMaker.dayTimer=0; print("[PlanerMaker] Royal Planer Maker System initialized (6 products, 4 buildings)") end
function PlanerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlanerMaker.maker={name=n or ("Gladilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gladilnikar najet: %s (spretnost: %d)",PlanerMaker.maker.name,s),"success") end; return true end
function PlanerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlanerMaker.build(id) local ok,e=PlanerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlanerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlanerMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlanerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlanerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PlanerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PlanerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and PlanerMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and PlanerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlanerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlanerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlanerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlanerMaker.buildings==0 then return false,"Potrebna gladilniška delavnica" end; if not PlanerMaker.maker then return false,"Potreben gladilnikar" end; return true end
function PlanerMaker.make(pt,qty) qty=qty or 1; local ok,e=PlanerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PlanerMaker.woodStock=PlanerMaker.woodStock-d.woodCost*qty end; if d.ironCost then PlanerMaker.ironStock=PlanerMaker.ironStock-d.ironCost*qty end; if d.steelCost then PlanerMaker.steelStock=PlanerMaker.steelStock-d.steelCost*qty end; if d.silverCost then PlanerMaker.silverStock=PlanerMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlanerMaker.goldStock=PlanerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlanerMaker.jewelStock=PlanerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlanerMaker.pearlStock=PlanerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlanerMaker.maker then t=math.max(1,t-math.floor(PlanerMaker.maker.skill/12)) end; table.insert(PlanerMaker.activeMaking,{id="planer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlanerMaker.completeMaking(m) local q=1.0+(PlanerMaker.getQualityBonus()/100); if PlanerMaker.maker then q=q+(PlanerMaker.maker.skill/140) end; q=math.min(2.5,q); PlanerMaker.productStock[m.productType]=(PlanerMaker.productStock[m.productType] or 0)+m.quantity; PlanerMaker.totalProducts=PlanerMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlanerMaker.maker then PlanerMaker.maker.itemsMade=PlanerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlanerMaker.maker.skill=math.min(100,PlanerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gladilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"planer.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function PlanerMaker.update(dt) if not _G.state then return end; PlanerMaker.dayTimer=PlanerMaker.dayTimer+dt; if PlanerMaker.dayTimer>=30 then PlanerMaker.dayTimer=0; for i=#PlanerMaker.activeMaking,1,-1 do local m=PlanerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlanerMaker.completeMaking(m); table.remove(PlanerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlanerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlanerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlanerMaker.getStats() return {woodStock=PlanerMaker.woodStock,ironStock=PlanerMaker.ironStock,steelStock=PlanerMaker.steelStock,silverStock=PlanerMaker.silverStock,goldStock=PlanerMaker.goldStock,jewelStock=PlanerMaker.jewelStock,pearlStock=PlanerMaker.pearlStock,productStock=PlanerMaker.productStock,numBuildings=#PlanerMaker.buildings,hasMaker=PlanerMaker.maker~=nil,makerName=PlanerMaker.maker and PlanerMaker.maker.name or "—",makerSkill=PlanerMaker.maker and PlanerMaker.maker.skill or 0,activeMaking=#PlanerMaker.activeMaking,totalProducts=PlanerMaker.totalProducts} end
return PlanerMaker
